local bxor = (bit32 and bit32.bxor) or (bit and bit.bxor)
local function xor(a, b)
    if bxor then return bxor(a, b) end
    local r, p = 0, 1
    while a > 0 or b > 0 do
        if (a % 2) ~= (b % 2) then r = r + p end
        a = (a - a % 2) / 2; b = (b - b % 2) / 2; p = p * 2
    end
    return r
end
-- returns the code, or nil if the key is wrong
local function decode(data, key)
    local s = table.concat(data)
    local kl = #key
    local out = {}
    for i = 1, #s do
        local j = i - 1
        out[i] = string.char(xor(xor(s:byte(i), key:byte(j % kl + 1)), (j * 31 + 7) % 256))
    end
    local code = table.concat(out)
    if code:sub(1, #MARK) ~= MARK then return nil end
    return code
end

local gui = Instance.new("ScreenGui")
gui.Name = "SHAD0WRIS_Mainhub"; gui.ResetOnSpawn = false; gui.DisplayOrder = 1000
pcall(function() gui.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
if not gui.Parent then gui.Parent = LP:WaitForChild("PlayerGui") end

local function corner(o, r) local c = Instance.new("UICorner", o); c.CornerRadius = UDim.new(0, r or 8); return c end
local frame = Instance.new("Frame", gui)
frame.Size = UDim2.fromOffset(340, 300)
frame.AnchorPoint = Vector2.new(0.5, 0.5)
frame.Position = UDim2.fromScale(0.5, 0.5)
frame.BackgroundColor3 = BG; frame.BorderSizePixel = 0
corner(frame)
local stroke = Instance.new("UIStroke", frame); stroke.Color = ACCENT; stroke.Thickness = 1.5

local title = Instance.new("TextLabel", frame)
title.Size = UDim2.new(1, -20, 0, 40); title.Position = UDim2.fromOffset(10, 10); title.BackgroundTransparency = 1
title.Text = "SHAD0WRIS_" .. LP.Name .. ".V5"; title.TextColor3 = TXT
title.Font = Enum.Font.GothamBold; title.TextSize = 16

local status = Instance.new("TextLabel", frame)
status.Size = UDim2.new(1, -20, 0, 20); status.Position = UDim2.new(0, 10, 1, -28); status.BackgroundTransparency = 1
status.Text = ""; status.TextColor3 = Color3.fromRGB(255, 200, 80)
status.Font = Enum.Font.Gotham; status.TextSize = 12

local function button(text, y, cb)
    local b = Instance.new("TextButton", frame)
    b.Size = UDim2.new(1, -40, 0, 40); b.Position = UDim2.fromOffset(20, y)
    b.BackgroundColor3 = PANEL; b.BorderSizePixel = 0; b.Text = text; b.TextColor3 = TXT
    b.Font = Enum.Font.GothamSemibold; b.TextSize = 14
    corner(b, 6)
    b.MouseButton1Click:Connect(cb)
    return b
end

-- compile first, so a bad version shows a message and the window stays open
local function openVersion(code)
    local run, err = loadstring(code)
    if not run then status.Text = "couldn't start that version: " .. tostring(err); return end
    gui:Destroy()
    run()
end

button("Public-Shad0wris", 60, function()
    local code = decode(PUB_DATA, PUB_KEY)
    if not code then status.Text = "public version is damaged - re-upload the hub"; return end
    openVersion(code)
end)

